import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class TestMain {
    static void main() {
        List<List<String >> res = new ArrayList<>();
        List<String> ans = new ArrayList<>();
        String[][] q = {{"1", "2", "5"}, {"1", "3"}};
        for(String[] a: q){
            res.add(Arrays.asList(a));
        }

        for(int i = 0 ; i < res.size() ; i ++){
            List<String> val = res.get(i);
            String x = val.get(0);
            if(val.size() > 1){
                x += "->" + val.get(val.size() - 1);
            }
            ans.add(x);
        }
        System.out.println(ans);
    }
}

package BinarySearch;

public class ArrangingCoins {
    //leetcode - 441
    //https://leetcode.com/problems/arranging-coins/description/
    /**
     * ou have n coins and you want to build a staircase with these coins. The staircase consists of k rows where the ith row has exactly i coins. The last row of the staircase may be incomplete.
     *
     * Given the integer n, return the number of complete rows of the staircase you will build.
     *
     *
     *
     * Example 1:
     *
     *
     * Input: n = 5
     * Output: 2
     * Explanation: Because the 3rd row is incomplete, we return 2.
     * Example 2:
     *
     *
     * Input: n = 8
     * Output: 3
     * Explanation: Because the 4th row is incomplete, we return 3.
     */

    static void main() {
        long n = 8;
        long start = 1;
        long end = n;
        long ans = 0;
        while (start <= end){
            long mid = start + (end - start) / 2;
            long count = (mid * (mid + 1)) / 2;
            if(count <= n){
                ans = mid;
                start = mid + 1;
            } else{
                end = mid - 1;
            }
        }
        System.out.println(ans);
    }
}

package BinarySearch;

public class BinarySearchRotateArray {
    //Leetcode - 33
    //https://leetcode.com/problems/search-in-rotated-sorted-array/description/
    //Asked in amazon and google
    /**
     * here is an integer array nums sorted in ascending order (with distinct values).
     *
     * Prior to being passed to your function, nums is possibly left rotated at an unknown index k (1 <= k < nums.length) such that the resulting array is [nums[k], nums[k+1], ..., nums[n-1], nums[0], nums[1], ..., nums[k-1]] (0-indexed). For example, [0,1,2,4,5,6,7] might be left rotated by 3 indices and become [4,5,6,7,0,1,2].
     *
     * Given the array nums after the possible rotation and an integer target, return the index of target if it is in nums, or -1 if it is not in nums.
     *
     * You must write an algorithm with O(log n) runtime complexity.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [4,5,6,7,0,1,2], target = 0
     * Output: 4
     * Example 2:
     *
     * Input: nums = [4,5,6,7,0,1,2], target = 3
     * Output: -1
     * Example 3:
     *
     * Input: nums = [1], target = 0
     * Output: -1
     */

    /**
     * The array will have pivot element, before numbers are in ascending order after numbers also will be in ascending order.
     * First we need to find that pivot index then we can do binary search separately 2 times for before and after arrays of the pivot
     * To find pivot element there are 4 cases.
     * Case 1 - if(arr[mid] > arr[mid + 1]) then arr[mid] is obviously pivot element
     * Case 2 - if(arr[mid] < arr[mid - 1]) then arr[mid - 1] is obviously pivot element.
     * Case 3 - if(arr[start] >= arr[mid]) then we don't need to check the numbers after arr[mid] because obviously it will be smaller numbers so it cant be mid in that case end = mid - 1
     * Case 4 - else - start = mid + 1
     * After finding the pivot index we can run binary search for both arrays separately and find the target's index.
     * This approach will not work if array have duplicate values
     */

    static void main() {
        int arr[] = {4,5,6,7,0,1,2};
        int target = 3;
        int pivotIndex = findPivotIndex(arr);
        int resIndex = getBinarySearchResult(arr, target, 0, pivotIndex);
        if(resIndex == -1){
            resIndex = getBinarySearchResult(arr, target, pivotIndex + 1, arr.length - 1);
        }
        System.out.println(resIndex);
    }

    static int findPivotIndex(int[] arr){
        int start = 0;
        int end = arr.length - 1;
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(end > mid  && arr[mid] > arr[mid + 1]){ //case 1
                return mid;
            }
            if(start < mid && arr[mid] < arr[mid - 1]){ //case 2
                return mid - 1;
            }
            if(arr[start] >= arr[mid]){//case 3
                end = mid - 1;
            } else{// case 4
                end = start + 1;
            }
        }
        return -1;
    }

    static int getBinarySearchResult(int[] arr, int target, int start, int end){
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(arr[mid] < target){
                start = mid + 1;
            } else if(arr[mid] > target){
                end = mid - 1;
            } else{
                return mid;
            }
        }
        return -1;
    }
}

package BinarySearch;

public class BinarySearchRotateArrayWithDuplicates {
    /**
     * The array will have pivot element, before numbers are in ascending order after numbers also will be in ascending order.
     * First we need to find that pivot index then we can do binary search separately 2 times for before and after arrays of the pivot
     * To find pivot element there are 4 cases.
     * Case 1 - if(arr[mid] > arr[mid + 1]) then arr[mid] is obviously pivot element
     * Case 2 - if(arr[mid] < arr[mid - 1]) then arr[mid - 1] is obviously pivot element.
     * This is the problem where array contains duplicate
     * Case 3 - We should skil the duplicates for eg if arr[start] == arr[mid] && arr[mid]==arr[end] we can skip start and end if they are not pivot by start++ and end --
     * but before doing case 3 we need to check if start or end is the pivot.
     * After finding the pivot index we can run binary search for both arr
     */

    static void main() {
        int arr[] = {4,5,5,6,6,7,0,1,2,2,2};
        int target = 1;
        int pivotIndex = findPivotIndex(arr);
        int resIndex = getBinarySearchResult(arr, target, 0, pivotIndex);
        if(resIndex == -1){
            resIndex = getBinarySearchResult(arr, target, pivotIndex + 1, arr.length - 1);
        }
        System.out.println(resIndex);
    }

    static int findPivotIndex(int[] arr){
        int start = 0;
        int end = arr.length - 1;
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(end > mid  && arr[mid] > arr[mid + 1]){ //case 1
                return mid;
            }
            if(start < mid && arr[mid] < arr[mid - 1]){ //case 2
                return mid - 1;
            }
            //case 3 we want to check if there are duplicates
            if(arr[start] == arr[mid] && arr[mid] == arr[end]){
                //then these are duplicates we should increment the start and decrement the end.
                //but before doing that we should check if start and end are pivot
                if(arr[start] > arr[start + 1]){
                    return start;
                }
                if(arr[end] < arr[end - 1]){
                    return end - 1;
                }
                start ++;
                end --;
            }
            //if left side is sorted that is arr[start] < arr[mid] then pivot should be in right side
            if(arr[start] < arr[mid] || (arr[start] == arr[mid] && arr[mid] > arr[end])){ //if arr[start] == arr[mid] then we should see if the end is < arr[mid] so we can move start index
                start = mid + 1;
            } else{ //if not the case then end will be moved before to find pivot in that range.
                end = mid - 1;
            }
        }
        return -1;
    }

    static int getBinarySearchResult(int[] arr, int target, int start, int end){
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(arr[mid] < target){
                start = mid + 1;
            } else if(arr[mid] > target){
                end = mid - 1;
            } else{
                return mid;
            }
        }
        return -1;
    }
}

package BinarySearch;

public class CielingProblem {
    //ceiling problem returns the smallest value which is >= the target from the sorted array.
    //input - Array of size N and the target.
    //Since it is sorted array we can use binary search for the process.
    //worst case time complexity of binary search is O(logn)
    static void main() {
        int[] array = {1,2,6,8,13,16,27,48,97};
        int target = 14;
        int result = getCeilingNumber(array, target);
        System.out.println(result);
    }

    static int getCeilingNumber(int[] array, int target) {
        int start = 0;
        int end = array.length - 1;
        if(target > array[end]){
            return -1;
        }
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(array[mid] == target){
                return array[mid];
            } else if(array[mid] > target){
                end = mid - 1;
            } else{
                start = mid + 1;
            }
        }
        return array[start];
    }
}

package BinarySearch;

public class FindGuessingNumber {
    //leetcode - 374 - easy
    //https://leetcode.com/problems/guess-number-higher-or-lower/description/
    /**
     * We are playing the Guess Game. The game is as follows:
     *
     * I pick a number from 1 to n. You have to guess which number I picked (the number I picked stays the same throughout the game).
     *
     * Every time you guess wrong, I will tell you whether the number I picked is higher or lower than your guess.
     *
     * You call a pre-defined API int guess(int num), which returns three possible results:
     *
     * -1: Your guess is higher than the number I picked (i.e. num > pick).
     * 1: Your guess is lower than the number I picked (i.e. num < pick).
     * 0: your guess is equal to the number I picked (i.e. num == pick).
     * Return the number that I picked.
     *
     *
     *
     * Example 1:
     *
     * Input: n = 10, pick = 6
     * Output: 6
     * Example 2:
     *
     * Input: n = 1, pick = 1
     * Output: 1
     * Example 3:
     *
     * Input: n = 2, pick = 1
     * Output: 1
     */

    static void main() {
        int number = 10;
        int pick = 6;
        int start = 1;
        int end = number;
        while (start <= number){
            int mid = start + (end - start) / 2;
            int value = guess(mid,pick);
            if(value == -1){
                end = mid - 1;
            } else if (value == 1) {
                start = mid + 1;
            } else {
                System.out.println(mid);
                return;
            }
        }
    }

    static int guess(int value, int number){
        if(value < number){
            return 1;
        } else if (value > number) {
            return -1;
        }
        return 0;
    }
}

package BinarySearch;

public class FindTargetInInfiniteArray {
    // We don't know the size of the array so we cant use array.length.
    //Instead we can start with first 2 number see whether the target lies between them. If not we can move start to 3rd element and end to 2^ like 4 then 8,...
    //If it lies between then we can perform binary search since it is a sorted array.
    static void main() {
        int arr[] = {3, 5, 7, 9, 10, 90, 100, 130, 140, 160, 170};
        int target = 170;
        System.out.println(findRange(arr, target));
    }
    static int findRange(int[] arr, int target){
        int start = 0;
        int end = 1;
        try {
            while (target > arr[end]) {
                int newStart = end + 1; //new start index will be from the next index of end
                end = end + (end - start + 1) * 2; //end - start + 1 is the size of the previously processed chunk now doubling the size for next chunk
                start = newStart;
            }
        } catch (ArrayIndexOutOfBoundsException e){
            end = arr.length; //Need to check for alternative approach. This cant be true coz this is infinite length array
        }
            return binarySearch(arr, target, start, end);
    }

    static int binarySearch(int[] arr, int target, int start, int end){
        while(start <= end){
            int mid = start + (end - start) / 2;
            if(arr[mid] == target){
                return mid;
            } else if (target > arr[mid]) {
                start = mid + 1;
            } else{
                end = mid - 1;
            }
        }
        return -1;
    }
}

package BinarySearch;

public class FindTargetInMountainArray {
    //leetcode question - 1095
    //https://leetcode.com/problems/find-in-mountain-array/description/
    /**
     * You may recall that an array arr is a mountain array if and only if:
     *
     * arr.length >= 3
     * There exists some i with 0 < i < arr.length - 1 such that:
     * arr[0] < arr[1] < ... < arr[i - 1] < arr[i]
     * arr[i] > arr[i + 1] > ... > arr[arr.length - 1]
     * Given a mountain array mountainArr, return the minimum index such that mountainArr.get(index) == target. If such an index does not exist, return -1.
     *
     * You cannot access the mountain array directly. You may only access the array using a MountainArray interface:
     *
     * MountainArray.get(k) returns the element of the array at index k (0-indexed).
     * MountainArray.length() returns the length of the array.
     * Submissions making more than 100 calls to MountainArray.get will be judged Wrong Answer. Also, any solutions that attempt to circumvent the judge will result in disqualification.
     * Example 1:
     *
     * Input: mountainArr = [1,2,3,4,5,3,1], target = 3
     * Output: 2
     * Explanation: 3 exists in the array, at index=2 and index=5. Return the minimum index, which is 2.
     * Example 2:
     *
     * Input: mountainArr = [0,1,2,4,2,1], target = 3
     * Output: -1
     * Explanation: 3 does not exist in the array, so we return -1.
     */
    //Mountain array is given as input and a target is given we need to find the smallest index of the target in the array
    //The approach is first we need to find the peakest element index from the array.
    //From that we need to do order agnostic binary search (i.e) first we should search in first half (ascending) array in the mountain array.
    //If the target is found that will be the result because mountain array wont have duplicates.
    //If the target is not found then we should search in next half (i.e) descending array.
    //If target is not found in that return -1.
    static void main() {
        int mountainArr[] = {0,1,2,4,2,1};
        int target = 3;
        int peakIndex = findPeakIndex(mountainArr);
        int resultIndex = findUsingBinarySearch(mountainArr, target, 0, peakIndex, true); //checking in the ascending array so boolean is passed.
        if(resultIndex == -1){ //if target not found in ascending array go for descensding
            resultIndex = findUsingBinarySearch(mountainArr, target, peakIndex, mountainArr.length - 1,false);
        }
        System.out.println(resultIndex);
    }

    static int findPeakIndex(int[] arr){
        int start = 0;
        int end = arr.length - 1;
        while (start != end){
            int mid = start + (end - start) / 2;
            if(arr[mid] > arr[mid + 1]){
                end = mid;
            } else if(arr[mid] < arr[mid + 1]){
                start = mid + 1;
            }
        }
        return start; //start and end both points to peak index so we can return anything.
    }

    static int findUsingBinarySearch(int[] arr, int target, int start, int end, boolean isAscending){
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(arr[mid] == target){
                return mid;
            } else if(arr[mid] < target){
                if(isAscending){
                    start = mid + 1;
                } else{
                    end = mid - 1;
                }
            } else{
                if(isAscending){
                    end = mid - 1;
                } else{
                    start = mid + 1;
                }
            }
        }
        return -1;
    }
}

package BinarySearch;

public class FirstBadVersion {
    //leetcode - 278
    //https://leetcode.com/problems/first-bad-version/description/
    /**
     * You are a product manager and currently leading a team to develop a new product. Unfortunately, the latest version of your product fails the quality check. Since each version is developed based on the previous version, all the versions after a bad version are also bad.
     *
     * Suppose you have n versions [1, 2, ..., n] and you want to find out the first bad one, which causes all the following ones to be bad.
     *
     * You are given an API bool isBadVersion(version) which returns whether version is bad. Implement a function to find the first bad version. You should minimize the number of calls to the API.
     *
     *
     *
     * Example 1:
     *
     * Input: n = 5, bad = 4
     * Output: 4
     * Explanation:
     * call isBadVersion(3) -> false
     * call isBadVersion(5) -> true
     * call isBadVersion(4) -> true
     * Then 4 is the first bad version.
     * Example 2:
     *
     * Input: n = 1, bad = 1
     * Output: 1
     */

    static void main() {
        int num = 5;
        int bad = 4;
        int start = 1;
        int end = num;
        int ans = 0;
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(isBadVersion(mid, bad)){
                ans = mid;
                end = mid - 1;
            } else {
                start = mid + 1;
            }
        }
        System.out.println(ans);
    }

    static boolean isBadVersion(int num, int bad){
        if(num == bad){
            return true;
        }
        return false;
    }
}

package BinarySearch;

public class FloorProblem {
    //Floor problem returns the largest value which is <= the target from the sorted array.
    //input - Array of size N and the target.
    //Since it is sorted array we can use binary search for the process.
    //worst case time complexity of binary search is O(logn)
    static void main() {
        int[] array = {1,2,6,8,13,16,27,48,97};
        int target = 14;
        int result = getFloorNumber(array, target);
        System.out.println(result);
    }

    static int getFloorNumber(int[] array, int target) {
        int start = 0;
        int end = array.length - 1;
        if(target > array[end]){
            return -1;
        }
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(array[mid] == target){
                return array[mid];
            } else if(array[mid] > target){
                end = mid - 1;
            } else{
                start = mid + 1;
            }
        }
        return array[end];
    }
}

package BinarySearch;

public class KthMissingPositiveInteger {
    //Leetcode - 1539
    //https://leetcode.com/problems/kth-missing-positive-number/description/
    /**
     * Given an array arr of positive integers sorted in a strictly increasing order, and an integer k.
     *
     * Return the kth positive integer that is missing from this array.
     *
     *
     *
     * Example 1:
     *
     * Input: arr = [2,3,4,7,11], k = 5
     * Output: 9
     * Explanation: The missing positive integers are [1,5,6,8,9,10,12,13,...]. The 5th missing positive integer is 9.
     * Example 2:
     *
     * Input: arr = [1,2,3,4], k = 2
     * Output: 6
     * Explanation: The missing positive integers are [5,6,7,...]. The 2nd missing positive integer is 6.
     */

    static void main() {
        int arr[] = {2,3,4,7,11};
        int k = 5;
        int start = 0;
        int end = arr.length - 1;
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(arr[mid] - mid - 1 < k){ //this is the formula for example the mid is 4 and we want to see what index is mid in this input its 2 but actually 4 need to be in index 3 so we know 1 element is less so we move start = mid + 1
                start = mid + 1;
            } else{ //if not we move end
                end = mid - 1;
            }
        }
        System.out.println(start + k);
    }
}

package BinarySearch;

public class MatrixTarget {
    static void main() {
        int[][] matrix = {{1,2,3},{4,5,6},{7,8,9}};
        int target = 7;
        int[] ans = getRowAndColIndex(matrix, target);
        System.out.println(ans[0] + " " + ans[1]);
    }

    static int[] getRowAndColIndex(int[][] matrix, int target){
        int start = 0;
        int end = matrix.length - 1;
        while (start < matrix.length && end >= 0){
            if(matrix[start][end] == target){
                return new int[]{start, end};
            }
            else if(matrix[start][end] > target){
                end --;
            }
            else {
                start ++;
            }
        }
        return new int[] {-1,-1};
    }
}

package BinarySearch;

public class MountainPeakIndex {
    //Leetcode question - 852, 162
    // https://leetcode.com/problems/peak-index-in-a-mountain-array/description/
    //https://leetcode.com/problems/find-peak-element/submissions/1847537355/
    //input array like [0,1,2,3,2,1] - it will increase at first then decrease, we need to find the peak index in this case peak element is 3 and its index is 3
    //also called as biotonic array

    /**
     * ou are given an integer mountain array arr of length n where the values increase to a peak element and then decrease.
     *
     * Return the index of the peak element.
     *
     * Your task is to solve it in O(log(n)) time complexity.
     *
     *
     *
     * Example 1:
     *
     * Input: arr = [0,1,0]
     *
     * Output: 1
     *
     * Example 2:
     *
     * Input: arr = [0,2,1,0]
     *
     * Output: 1
     *
     * Example 3:
     *
     * Input: arr = [0,10,5,2]
     *
     * Output: 1
     */

    static void main() {
        int arr[] = {0,2,1,0};
        System.out.println(findPeak(arr));
    }
    static int findPeak(int[] arr){
        int start = 0;
        int end = arr.length - 1;
        while(start != end){ //in the end the start and end index both will face the peakest number
            int mid = start + (end - start) / 2;
            if(arr[mid] > arr[mid + 1]){ //if mid is > mid + 1 then we are in the descending side so we should move the end to mid
                end = mid;
            } else if(arr[mid] < arr[mid + 1]){ //if mid is < mid + 1 then we are in the ascending array we can move start to the next element of the mid.
                start = mid + 1;
            }
        }
        return start; //start and end gonna be same at the end so we can return any one.
    }
}

package BinarySearch;

public class NextGreatestLetter {
    //Leetcode question 744
    //https://leetcode.com/problems/find-smallest-letter-greater-than-target/
    /**You are given an array of characters letters that is sorted in non-decreasing order, and a character target. There are at least two different characters in letters.

     Return the smallest character in letters that is lexicographically greater than target. If such a character does not exist, return the first character in letters.



     Example 1:

     Input: letters = ["c","f","j"], target = "a"
     Output: "c"
     Explanation: The smallest character that is lexicographically greater than 'a' in letters is 'c'.
     Example 2:

     Input: letters = ["c","f","j"], target = "c"
     Output: "f"
     Explanation: The smallest character that is lexicographically greater than 'c' in letters is 'f'.
     Example 3:

     Input: letters = ["x","x","y","y"], target = "z"
     Output: "x"
     Explanation: There are no characters in letters that is lexicographically greater than 'z' so we return letters[0].

     **/

    static void main() {
        char[] letters = {'c','f','j'};
        char target = 'f';
        int start = 0;
        int end = letters.length - 1;
        // if(target >= letters[end]){
        //     return letters[0];
        // }
        while (start <= end){
            int mid = start + (end - start) / 2;
            if(letters[mid] > target){
                end = mid - 1;
            } else{
                start = mid + 1;
            }
        }
        System.gc();
        System.out.println(letters[start % letters.length]);
    }
}

package BinarySearch;

public class PerfectSquare {
    //leetcode - 367
    /**
     * Given a positive integer num, return true if num is a perfect square or false otherwise.
     *
     * A perfect square is an integer that is the square of an integer. In other words, it is the product of some integer with itself.
     *
     * You must not use any built-in library function, such as sqrt.
     *
     *
     *
     * Example 1:
     *
     * Input: num = 16
     * Output: true
     * Explanation: We return true because 4 * 4 = 16 and 4 is an integer.
     * Example 2:
     *
     * Input: num = 14
     * Output: false
     * Explanation: We return false because 3.742 * 3.742 = 14 and 3.742 is not an integer.
     */

    static void main() {
        int num = 121;
        System.out.println(isPerfectSquare(num));
    }

    static boolean isPerfectSquare(int num){
        long start = 1;
        long end = num;
        while (start <= end){
            long mid = start + (end - start) / 2;
            long res = mid * mid;
            if(res == num){
                return true;
            } else if (res > num) {
                end = mid - 1;
            } else{
                start = mid + 1;
            }
        }
        return false;
    }
}

