     *
     * If target is not found in the array, return [-1, -1].
     *
     * You must write an algorithm with O(log n) runtime complexity.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [5,7,7,8,8,10], target = 8
     * Output: [3,4]
     * Example 2:
     *
     * Input: nums = [5,7,7,8,8,10], target = 6
     * Output: [-1,-1]
     * Example 3:
     *
     * Input: nums = [], target = 0
     * Output: [-1,-1]
     */

    static void main() {
        int nums[] = {5,7,7,8,8,10};
        int target = 8;
        int arr[] = searchRange(nums, target);
        System.out.println(arr[0]+ " " +arr[1]);
    }

    public static int[] searchRange(int[] nums, int target) {
        int ans[] = {-1,-1};
        ans[0] = searchUsingBinarySearch(nums, target, true);
        if(ans[0] != -1)
            ans[1] = searchUsingBinarySearch(nums, target, false);
        return ans;
    }

    public static int searchUsingBinarySearch(int[] nums, int target, boolean isStart){
        int res = -1;
        int start = 0;
        int end = nums.length - 1;
        while(start <= end){
            int mid = start + (end-start) / 2;
            if(nums[mid] < target){
                start = mid + 1;
            } else if(nums[mid] > target){
                end = mid - 1;
            } else{
                res = mid;
                if(isStart){
                    end = mid - 1;
                } else{
                    start = mid + 1;
                }
            }
        }
        return res;
    }
}

