package CompanyQuestions.Microsoft;

import java.util.HashMap;

public class RemoveDuplicatesFromSortedArray2 {
    //Leetcode - 80
    //https://leetcode.com/problems/remove-duplicates-from-sorted-array-ii/description/
    /**
     * Given an integer array nums sorted in non-decreasing order, remove some duplicates in-place such that each unique element appears at most twice. The relative order of the elements should be kept the same.
     *
     * Since it is impossible to change the length of the array in some languages, you must instead have the result be placed in the first part of the array nums. More formally, if there are k elements after removing the duplicates, then the first k elements of nums should hold the final result. It does not matter what you leave beyond the first k elements.
     *
     * Return k after placing the final result in the first k slots of nums.
     *
     * Do not allocate extra space for another array. You must do this by modifying the input array in-place with O(1) extra memory.
     *
     * Custom Judge:
     *
     * The judge will test your solution with the following code:
     *
     * int[] nums = [...]; // Input array
     * int[] expectedNums = [...]; // The expected answer with correct length
     *
     * int k = removeDuplicates(nums); // Calls your implementation
     *
     * assert k == expectedNums.length;
     * for (int i = 0; i < k; i++) {
     *     assert nums[i] == expectedNums[i];
     * }
     * If all assertions pass, then your solution will be accepted.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [1,1,1,2,2,3]
     * Output: 5, nums = [1,1,2,2,3,_]
     * Explanation: Your function should return k = 5, with the first five elements of nums being 1, 1, 2, 2 and 3 respectively.
     * It does not matter what you leave beyond the returned k (hence they are underscores).
     * Example 2:
     *
     * Input: nums = [0,0,1,1,1,1,2,3,3]
     * Output: 7, nums = [0,0,1,1,2,3,3,_,_]
     * Explanation: Your function should return k = 7, with the first seven elements of nums being 0, 0, 1, 1, 2, 3 and 3 respectively.
     * It does not matter what you leave beyond the returned k (hence they are underscores).
     */

    static void main() {
        int[] nums = {0,0,1,1,1,2,2,3,3,4};
        int k = optimised(nums);
        for (int i = 0; i < k; i++) {
            System.out.println(nums[i]);
        }
    }
//My solution - 4ms
    static int removeDuplicates2(int[] nums) {
        int i = 1;
        HashMap<Integer, Integer> res = new HashMap<>();
        res.put(nums[0], 1);
        for (int j = 1; j < nums.length; j++) {
            if ((nums[j] != nums[j - 1]) || (nums[j] == nums[j - 1] && res.get(nums[j]) < 2)) {
                nums[i] = nums[j];
                i++;
            }
            res.put(nums[j], res.getOrDefault(nums[j], 0) + 1);
        }
        return i;
    }
//0ms solution
    static int optimised(int[] nums){
        int i = 2;
        for(int j = 2 ; j < nums.length ; j ++){
            if(nums[j] != nums[i - 2]){
                nums[i] = nums[j];
                i ++;
            }
        }
        return i;
    }
}

package CompanyQuestions.Microsoft;

public class RomanToInteger {
    //Leetcode -13
    //https://leetcode.com/problems/roman-to-integer/
    /**
     * Roman numerals are represented by seven different symbols: I, V, X, L, C, D and M.
     *
     * Symbol       Value
     * I             1
     * V             5
     * X             10
     * L             50
     * C             100
     * D             500
     * M             1000
     * For example, 2 is written as II in Roman numeral, just two ones added together. 12 is written as XII, which is simply X + II. The number 27 is written as XXVII, which is XX + V + II.
     *
     * Roman numerals are usually written largest to smallest from left to right. However, the numeral for four is not IIII. Instead, the number four is written as IV. Because the one is before the five we subtract it making four. The same principle applies to the number nine, which is written as IX. There are six instances where subtraction is used:
     *
     * I can be placed before V (5) and X (10) to make 4 and 9.
     * X can be placed before L (50) and C (100) to make 40 and 90.
     * C can be placed before D (500) and M (1000) to make 400 and 900.
     * Given a roman numeral, convert it to an integer.
     *
     * Example 1:
     *
     * Input: s = "III"
     * Output: 3
     * Explanation: III = 3.
     * Example 2:
     *
     * Input: s = "LVIII"
     * Output: 58
     * Explanation: L = 50, V= 5, III = 3.
     * Example 3:
     *
     * Input: s = "MCMXCIV"
     * Output: 1994
     * Explanation: M = 1000, CM = 900, XC = 90 and IV = 4.
     */

    static void main() {
        String roman = "MCMXCIV";
        System.out.println(romanToInt(roman));
    }

    static int romanToInt(String s){
        int total = 0;
        int i = 0;
        while(i < s.length()){
            if(s.charAt(i) == 'I'){
                if(i + 1 < s.length() && s.charAt(i+1) == 'V'){
                    total += 4;
                    i+=2;
                } else if(i + 1 < s.length() && s.charAt(i+1)=='X'){
                    total+=9;
                    i+=2;
                } else{
                    total+=1;
                    i+=1;
                }
            } else if(s.charAt(i) == 'X'){
                if(i + 1 < s.length() && s.charAt(i+1) == 'L'){
                    total += 40;
                    i+=2;
                } else if(i + 1 <s.length() && s.charAt(i + 1) == 'C'){
                    total += 90;
                    i += 2;
                } else{
                    total += 10;
                    i +=1;
                }
            } else if(s.charAt(i) == 'C'){
                if(i + 1 < s.length() && s.charAt(i + 1) == 'D'){
                    total += 400;
                    i += 2;
                } else if(i + 1 < s.length() && s.charAt(i + 1) == 'M'){
                    total += 900;
                    i += 2;
                } else{
                    total += 100;
                    i += 1;
                }
            } else if(s.charAt(i) == 'V'){
                total += 5;
                i +=1;
            } else if(s.charAt(i) == 'L'){
                total += 50;
                i += 1;
            } else if(s.charAt(i) == 'D'){
                total += 500;
                i += 1;
            } else{
                total += 1000;
                i += 1;
            }
        }
        return total;
    }
}

package CompanyQuestions.Microsoft;

import java.util.HashMap;

public class TwoSum {
    //Leetcode - 1
    //https://leetcode.com/problems/two-sum/description/
    /**
     * Given an array of integers nums and an integer target, return indices of the two numbers such that they add up to target.
     *
     * You may assume that each input would have exactly one solution, and you may not use the same element twice.
     *
     * You can return the answer in any order.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [2,7,11,15], target = 9
     * Output: [0,1]
     * Explanation: Because nums[0] + nums[1] == 9, we return [0, 1].
     * Example 2:
     *
     * Input: nums = [3,2,4], target = 6
     * Output: [1,2]
     * Example 3:
     *
     * Input: nums = [3,3], target = 6
     * Output: [0,1]
     */

    static void main() {
        int[] arr = {2,7,11,15};
        int target = 9;
        int[] res = anotherTwoSum(arr, target);
        System.out.println(res[0] + " " + res[1]);
    }

    static int[] twoSum(int[] nums, int target) { //rumtime 2ms
        HashMap<Integer, Integer> map = new HashMap<>();
        for(int i = 0; i < nums.length; i ++){
            if(map.containsKey(target - nums[i])){
                return new int[]{map.get(target - nums[i]), i};
            }
            map.put(nums[i],i);
        }
        return new int[]{-1,-1};
    }

    static int[] anotherTwoSum(int[] nums, int target){ //0ms
        int[] res = new int[2];
        for (int i = 1; i < nums.length; i++) {
            for (int j = i; j < nums.length; j++) {
                if (nums[j - i] + nums[j] == target) {
                    res[0] = j - i;
                    res[1] = j;
                    return res;
                }
            }
        }
        return res;
    }
}

