public class FindEventualState {
    //802
    //https://leetcode.com/problems/find-eventual-safe-states/description/

    /**
     * There is a directed graph of n nodes with each node labeled from 0 to n - 1. The graph is represented by a 0-indexed 2D integer array graph where graph[i] is an integer array of nodes adjacent to node i, meaning there is an edge from node i to each node in graph[i].
     * <p>
     * A node is a terminal node if there are no outgoing edges. A node is a safe node if every possible path starting from that node leads to a terminal node (or another safe node).
     * <p>
     * Return an array containing all the safe nodes of the graph. The answer should be sorted in ascending order.
     * <p>
     * <p>
     * <p>
     * Example 1:
     * <p>
     * Illustration of graph
     * Input: graph = [[1,2],[2,3],[5],[0],[5],[],[]]
     * Output: [2,4,5,6]
     * Explanation: The given graph is shown above.
     * Nodes 5 and 6 are terminal nodes as there are no outgoing edges from either of them.
     * Every path starting at nodes 2, 4, 5, and 6 all lead to either node 5 or 6.
     * Example 2:
     * <p>
     * Input: graph = [[1,2,3,4],[1,2],[3,4],[0,4],[]]
     * Output: [4]
     * Explanation:
     * Only node 4 is a terminal node, and every path starting at node 4 leads to node 4.
     * <p>
     * <p>
     * Constraints:
     * <p>
     * n == graph.length
     * 1 <= n <= 104
     * 0 <= graph[i].length <= n
     * 0 <= graph[i][j] <= n - 1
     * graph[i] is sorted in a strictly increasing order.
     * The graph may contain self-loops.
     * The number of edges in the graph will be in the range [1, 4 * 104].
     */

    static void main() {
        int[][] graph = {
                {1, 2},
                {2, 3},
                {5},
                {0},
                {5},
                {},
                {}
        };
        System.out.println(eventualSafeNodes(graph));
    }

    static List<Integer> eventualSafeNodes(int[][] graph) {
        //List<List<Integer>> adjList = new ArrayList<>();
        int n = graph.length;
        //here graph itself an adjList because every index values says to which node it goes to for eg index 0 = [1,2] so 0 node goes to 1 and 2 and so on
        /**for(int i = 0 ; i < n ; i ++){
         adjList.add(new ArrayList<>());
         }
         //create adjList
         for(int i = 0 ; i < n ; i ++){
         for(int j : graph[i]){
         adjList.get(i).add(j);
         }
         }**/
        int[] visited = new int[n];
        int[] pathVisited = new int[n];
        for(int i = 0 ; i < n ; i ++){
            if(visited[i] == 0){
                dfs(i, graph, visited, pathVisited);
            }
        }
        List<Integer> res = new ArrayList<>();
        //not cycle path nodes are the answer
        for(int i = 0 ; i < pathVisited.length ; i ++){
            if(pathVisited[i] == 0){
                res.add(i);
            }
        }
        return res;
    }

    static boolean dfs(int i, int[][] graph, int[] visited, int[] pathVisited){
        visited[i] = 1;
        pathVisited[i] = 1;
        for(int j : graph[i]){
            if(visited[j] == 0 && dfs(j, graph, visited, pathVisited)){
                return true;
            }
            //if path already visited now visiting again then cycle exixts
            if(pathVisited[j] == 1){
                return true;
            }
        }
        //mark 0 for not cycle paths
        pathVisited[i] = 0;
        return false;
    }

}

package Graph;

import java.util.*;

public class FloodFill {
    //773
    //https://leetcode.com/problems/flood-fill/description/
    /**
     * You are given an image represented by an m x n grid of integers image, where image[i][j] represents the pixel value of the image. You are also given three integers sr, sc, and color. Your task is to perform a flood fill on the image starting from the pixel image[sr][sc].
     *
     * To perform a flood fill:
     *
     * Begin with the starting pixel and change its color to color.
     * Perform the same process for each pixel that is directly adjacent (pixels that share a side with the original pixel, either horizontally or vertically) and shares the same color as the starting pixel.
     * Keep repeating this process by checking neighboring pixels of the updated pixels and modifying their color if it matches the original color of the starting pixel.
     * The process stops when there are no more adjacent pixels of the original color to update.
     * Return the modified image after performing the flood fill.
     *
     *
     *
     * Example 1:
     *
     * Input: image = [[1,1,1],[1,1,0],[1,0,1]], sr = 1, sc = 1, color = 2
     *
     * Output: [[2,2,2],[2,2,0],[2,0,1]]
     *
     * Explanation:
     *
     *
     *
     * From the center of the image with position (sr, sc) = (1, 1) (i.e., the red pixel), all pixels connected by a path of the same color as the starting pixel (i.e., the blue pixels) are colored with the new color.
     *
     * Note the bottom corner is not colored 2, because it is not horizontally or vertically connected to the starting pixel.
     *
     * Example 2:
     *
     * Input: image = [[0,0,0],[0,0,0]], sr = 0, sc = 0, color = 0
     *
     * Output: [[0,0,0],[0,0,0]]
     *
     * Explanation:
     *
     * The starting pixel is already colored with 0, which is the same as the target color. Therefore, no changes are made to the image.
     *
     *
     *
     * Constraints:
     *
     * m == image.length
     * n == image[i].length
     * 1 <= m, n <= 50
     * 0 <= image[i][j], color < 216
     * 0 <= sr < m
     * 0 <= sc < n
     */

    static void main() {
        int[][] image = {
                {1,1,1},
                {1,1,0},
                {1,0,1}
        };
        int sr = 1;
        int sc = 1;
        int color = 2;
        int[][] res = floodFill(image, sr, sc, color);
        for(int[] mat : res){
            for(int i: mat){
                System.out.print(i + " ");
            }
            System.out.println();
        }
    }

    static int[][] floodFill(int[][] image, int sr, int sc, int color) {
        return dfsMethod(image, sr, sc, color); //1ms
        //return bfsMethod(image, sr, sc, color); //2ms
    }

    static int[][] dfsMethod(int[][] image, int sr, int sc, int color){
        int n = image.length;
        int m = image[0].length;
        int[][] visited = new int[n][m];
        int[][] resultArr = new int[n][m];
        for(int i = 0 ; i < n ; i ++){
            for(int j = 0 ; j < m ; j ++){
                resultArr[i][j] = image[i][j];
            }
        }
        int val = image[sr][sc];
        resultArr[sr][sc] = color;
        dfs(image, visited, resultArr, sr, sc, val, color);
        return resultArr;
    }

    static void dfs(int[][] image, int[][] visited, int[][] resultArr, int r, int c, int val, int color){
        visited[r][c] = 1;
        if(r > 0 && image[r-1][c] == val && visited[r-1][c] == 0){
            resultArr[r-1][c] = color;
            dfs(image, visited, resultArr, r-1, c, val, color);
        }
        if(r < image.length - 1 && image[r+1][c] == val && visited[r+1][c] == 0){
            resultArr[r+1][c] = color;
            dfs(image, visited, resultArr, r+1, c, val, color);
        }
        if(c > 0 && image[r][c - 1] == val && visited[r][c - 1] == 0){
            resultArr[r][c - 1] = color;
            dfs(image, visited, resultArr, r, c - 1, val, color);
        }
        if(c < image[0].length -1  && image[r][c + 1] == val && visited[r][c + 1] == 0){
            resultArr[r][c + 1] = color;
            dfs(image, visited, resultArr, r, c + 1, val, color);
        }
    }

    static int[][] bfsMethod(int[][] image, int sr, int sc, int color){
        int n = image.length;
        int m = image[0].length;
        int[][] visited = new int[n][m];
        int[][] resultArr = new int[n][m];
        for(int i = 0 ; i < n ; i ++){
            for(int j = 0 ; j < m ; j ++){
                resultArr[i][j] = image[i][j];
            }
        }
        int val = image[sr][sc];
        resultArr[sr][sc] = color;
        bfs(image, visited, resultArr, sr, sc, val, color);
        return resultArr;
    }

    static void bfs(int[][] grid, int[][] visited, int[][] resultArr, int row, int col, int val, int color){
        Queue<List<Integer>> queue = new LinkedList<>();
        List<Integer> valArr = new ArrayList<>();
        //add the initial indices to queue
        valArr.add(row);
        valArr.add(col);
        queue.offer(valArr);
        //mark visited
        visited[row][col] = 1;
        while(!queue.isEmpty()){
            //process queue
            List<Integer> land = queue.poll();
            int r = land.get(0);
            int c = land.get(1);
            List<Integer> newLand;
            //add neighbouring lands and mark visited
            if(r > 0 && grid[r-1][c] == val && visited[r-1][c] != 1){
                newLand = new ArrayList<>();
                newLand.add(r-1);
                newLand.add(c);
                queue.offer(newLand);
                visited[r-1][c] = 1;
                resultArr[r-1][c] = color;
            }
            if(r < grid.length - 1 && grid[r + 1][c] == val && visited[r + 1][c] != 1){
                newLand = new ArrayList<>();
                newLand.add(r+1);
                newLand.add(c);
                queue.offer(newLand);
                visited[r+1][c] = 1;
                resultArr[r+1][c] = color;
            }
            if(c > 0 && grid[r][c-1] == val && visited[r][c-1] != 1){
                newLand = new ArrayList<>();
                newLand.add(r);
                newLand.add(c-1);
                queue.offer(newLand);
                visited[r][c-1] = 1;
                resultArr[r][c-1]=color;
            }
            if(c < grid[0].length - 1 && grid[r][c + 1] == val && visited[r][c+1] != 1){
                newLand = new ArrayList<>();
                newLand.add(r);
                newLand.add(c + 1);
                queue.offer(newLand);
                visited[r][c + 1] = 1;
                resultArr[r][c+1]=color;
            }
        }
    }
}

package Graph;

public class IslandPerimeter {
    //463
    //https://leetcode.com/problems/island-perimeter/description/?envType=problem-list-v2&envId=depth-first-search
    /**
     * You are given row x col grid representing a map where grid[i][j] = 1 represents land and grid[i][j] = 0 represents water.
     *
     * Grid cells are connected horizontally/vertically (not diagonally). The grid is completely surrounded by water, and there is exactly one island (i.e., one or more connected land cells).
     *
     * The island doesn't have "lakes", meaning the water inside isn't connected to the water around the island. One cell is a square with side length 1. The grid is rectangular, width and height don't exceed 100. Determine the perimeter of the island.
     *
     *
     *
     * Example 1:
     *
     *
     * Input: grid = [[0,1,0,0],[1,1,1,0],[0,1,0,0],[1,1,0,0]]
     * Output: 16
     * Explanation: The perimeter is the 16 yellow stripes in the image above.
     * Example 2:
     *
     * Input: grid = [[1]]
     * Output: 4
     * Example 3:
     *
     * Input: grid = [[1,0]]
     * Output: 4
     *
     *
     * Constraints:
     *
     * row == grid.length
     * col == grid[i].length
     * 1 <= row, col <= 100
     * grid[i][j] is 0 or 1.
     * There is exactly one island in grid.
     */

    static void main() {
        int[][] grid = {
                {0,1,0,0},
                {1,1,1,0},
                {0,1,0,0},
                {1,1,0,0}
        };
        System.out.println(islandPerimeter(grid));
    }

    static int islandPerimeter(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] visited = new int[m][n];
        int perimeter = 0;
        for(int i = 0 ; i < m ; i ++){
            for(int j = 0 ; j < n ; j ++){
                if(visited[i][j] == 0 && grid[i][j] == 1){
                    perimeter += dfs(visited, grid, i, j);
                }
            }
        }
        return perimeter;
    }

    static int dfs(int[][] visited, int[][] grid, int r, int c){
        // Base cases for DFS recursion
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] == 0) {
            return 1; // Water contributes 1 to perimeter
        }
        if (visited[r][c] == 1) {
            return 0; // Already visited land cell
        }

        // Mark cell as visited
        visited[r][c] = 1;

        // Explore neighbors (up, down, left, right)
        return (dfs(visited,grid, r + 1, c) +
                dfs(visited,grid, r - 1, c) +
                dfs(visited,grid, r, c + 1) +
                dfs(visited,grid, r, c - 1));
    }
}

