package Leetcode;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;

public class NextGreatestNumber {
    //Leetcode - 496
    //https://leetcode.com/problems/next-greater-element-i/description/?envType=problem-list-v2&envId=array
    /**
     * The next greater element of some element x in an array is the first greater element that is to the right of x in the same array.
     *
     * You are given two distinct 0-indexed integer arrays nums1 and nums2, where nums1 is a subset of nums2.
     *
     * For each 0 <= i < nums1.length, find the index j such that nums1[i] == nums2[j] and determine the next greater element of nums2[j] in nums2. If there is no next greater element, then the answer for this query is -1.
     *
     * Return an array ans of length nums1.length such that ans[i] is the next greater element as described above.
     *
     *
     *
     * Example 1:
     *
     * Input: nums1 = [4,1,2], nums2 = [1,3,4,2]
     * Output: [-1,3,-1]
     * Explanation: The next greater element for each value of nums1 is as follows:
     * - 4 is underlined in nums2 = [1,3,4,2]. There is no next greater element, so the answer is -1.
     * - 1 is underlined in nums2 = [1,3,4,2]. The next greater element is 3.
     * - 2 is underlined in nums2 = [1,3,4,2]. There is no next greater element, so the answer is -1.
     * Example 2:
     *
     * Input: nums1 = [2,4], nums2 = [1,2,3,4]
     * Output: [3,-1]
     * Explanation: The next greater element for each value of nums1 is as follows:
     * - 2 is underlined in nums2 = [1,2,3,4]. The next greater element is 3.
     * - 4 is underlined in nums2 = [1,2,3,4]. There is no next greater element, so the answer is -1.
     *
     *
     * Constraints:
     *
     * 1 <= nums1.length <= nums2.length <= 1000
     * 0 <= nums1[i], nums2[i] <= 104
     * All integers in nums1 and nums2 are unique.
     * All the integers of nums1 also appear in nums2.
     */

    static void main() {
        int[] nums1 = {4,1,2};
        int[] nums2 = {1,3,4,2};
        HashMap<Integer,Integer> res = new HashMap<>();
        for(int i = 0 ; i < nums2.length ; i ++){
            res.put(nums2[i], i);
        }
        for(int i = 0 ; i < nums1.length ; i ++){
            nums1[i] = getNextGreatest(nums2, res.get(nums1[i]));
        }
        System.out.println(Arrays.toString(nums1));  //2ms solution
    }

    static int getNextGreatest(int[] nums2, int index){
        int max = nums2[index];
        for(int i = index + 1 ; i < nums2.length ; i ++){
            if(nums2[i] > max){
                return nums2[i];
            }
        }
        return -1;
    }
}

package Leetcode;

import java.util.ArrayList;
import java.util.List;

public class SummaryRanges {
    //leetcode - 228
    //https://leetcode.com/problems/summary-ranges/description/?envType=problem-list-v2&envId=array

    /**
     * ou are given a sorted unique integer array nums.
     *
     * A range [a,b] is the set of all integers from a to b (inclusive).
     *
     * Return the smallest sorted list of ranges that cover all the numbers in the array exactly. That is, each element of nums is covered by exactly one of the ranges, and there is no integer x such that x is in one of the ranges but not in nums.
     *
     * Each range [a,b] in the list should be output as:
     *
     * "a->b" if a != b
     * "a" if a == b
     *
     *
     * Example 1:
     *
     * Input: nums = [0,1,2,4,5,7]
     * Output: ["0->2","4->5","7"]
     * Explanation: The ranges are:
     * [0,2] --> "0->2"
     * [4,5] --> "4->5"
     * [7,7] --> "7"
     * Example 2:
     *
     * Input: nums = [0,2,3,4,6,8,9]
     * Output: ["0","2->4","6","8->9"]
     * Explanation: The ranges are:
     * [0,0] --> "0"
     * [2,4] --> "2->4"
     * [6,6] --> "6"
     * [8,9] --> "8->9"
     *
     *
     * Constraints:
     *
     * 0 <= nums.length <= 20
     * -231 <= nums[i] <= 231 - 1
     * All the values of nums are unique.
     * nums is sorted in ascending order.
     */

    static void main() {
        int[] nums = {0,1,2,4,5,7};
        System.out.println(summaryRanges(nums));
    }

    static List<String> summaryRanges(int[] nums) {
        List<String> res = new ArrayList<>();
        int i = 0;
        while(i < nums.length){
            StringBuilder sb = new StringBuilder();
            int j = i;
            while(j + 1 < nums.length && nums[j + 1] == nums[j] + 1){
                j ++;
            }
            if(i == j){
                sb.append(nums[i]);
            } else{
                sb.append(nums[i]);
                sb.append("->");
                sb.append(nums[j]);
            }
            res.add(sb.toString());
            i=j+1;
        }
        return res;
    }
}

package Leetcode.DailyChallenge;

public class FourDivisors {
    //4/1/26
    //1390
    //https://leetcode.com/problems/four-divisors/?envType=daily-question&envId=2026-01-04

    /**
     * Given an integer array nums, return the sum of divisors of the integers in that array that have exactly four divisors. If there is no such integer in the array, return 0.
     * <p>
     * <p>
     * <p>
     * Example 1:
     * <p>
     * Input: nums = [21,4,7]
     * Output: 32
     * Explanation:
     * 21 has 4 divisors: 1, 3, 7, 21
     * 4 has 3 divisors: 1, 2, 4
     * 7 has 2 divisors: 1, 7
     * The answer is the sum of divisors of 21 only.
     * Example 2:
     * <p>
     * Input: nums = [21,21]
     * Output: 64
     * Example 3:
     * <p>
     * Input: nums = [1,2,3,4,5]
     * Output: 0
     * <p>
     * <p>
     * Constraints:
     * <p>
     * 1 <= nums.length <= 104
     * 1 <= nums[i] <= 105
     */

    static void main() {
        int[] nums = {21, 4, 7};
        System.out.println(sumFourDivisors(nums));
    }

    static int sumFourDivisors(int[] nums) {
        int sum = 0;
        for(int n : nums){
            int count = 0;
            int currentSum = 0;
            for (int d = 1; d * d <= n; d++) {
                if (n % d == 0) {
                    // d is a divisor
                    count++;
                    currentSum += d;

                    // If d is not the square root, add its counterpart n/d
                    if (d * d != n) {
                        count++;
                        currentSum += n / d;
                    }
                }

                // Optimization: if we already have more than 4, stop
                if (count > 4) break;
            }
            if(count == 4){
                sum += currentSum;
            }
        }
        return sum;
    }
}

package Leetcode.DailyChallenge;

public class MaximumMatrixSum {
    //5/1/26
    //1975
    //https://leetcode.com/problems/maximum-matrix-sum/description/?envType=daily-question&envId=2026-01-05
    /**
     * You are given an n x n integer matrix. You can do the following operation any number of times:
     *
     * Choose any two adjacent elements of matrix and multiply each of them by -1.
     * Two elements are considered adjacent if and only if they share a border.
     *
     * Your goal is to maximize the summation of the matrix's elements. Return the maximum sum of the matrix's elements using the operation mentioned above.
     *
     *
     *
     * Example 1:
     *
     *
     * Input: matrix = [[1,-1],[-1,1]]
     * Output: 4
     * Explanation: We can follow the following steps to reach sum equals 4:
     * - Multiply the 2 elements in the first row by -1.
     * - Multiply the 2 elements in the first column by -1.
     * Example 2:
     *
     *
     * Input: matrix = [[1,2,3],[-1,-2,-3],[1,2,3]]
     * Output: 16
     * Explanation: We can follow the following step to reach sum equals 16:
     * - Multiply the 2 last elements in the second row by -1.
     *
     *
     * Constraints:
     *
     * n == matrix.length == matrix[i].length
     * 2 <= n <= 250
     * -105 <= matrix[i][j] <= 105
     */

    static void main() {
        int[][] matrix = {{1,2,3},{-1,-2,-3},{1,2,3}};
        System.out.println(maxMatrixSum(matrix));
    }

    static long maxMatrixSum(int[][] matrix) {
        /**
         Approach - Possible maximum value answer will be when all the numbers in matrix are positive.
         So if there are even number of negative numbers every numbers can be turned to positive so that will be the answer
         But if there is odd set of negative numbers then we should subtract only one negative number but that should be smallest number when it is changed to positive.
         We should subtrack 2 * min number because the min number will be already added to the total sum.
         */
        int min = Integer.MAX_VALUE;
        long total = 0;
        int neg = 0;
        for(int[] i : matrix){
            for(int j : i){
                total += Math.abs(j);
                if(j < 0){
                    neg ++;
                }
                min = Math.min(min, Math.abs(j));
            }
        }
        if(neg % 2 != 0){
            total -= (2 * min);
        }
        return total;
    }
}

