     * Example 2:
     *
     * Input: nums = [3,2,3,4], k = 5
     *
     * Output: 2
     *
     * Explanation:
     *
     * The subarray [3, 2] has distinct elements {3, 2} whose sum is 3 + 2 = 5, which is ​​​​​​​at least k = 5. Thus, the answer is 2.
     *
     * Example 3:
     *
     * Input: nums = [5,5,4], k = 5
     *
     * Output: 1
     *
     * Explanation:
     *
     * The subarray [5] has distinct elements {5} whose sum is 5, which is at least k = 5. Thus, the answer is 1.
     *
     *
     *
     * Constraints:
     *
     * 1 <= nums.length <= 105
     * 1 <= nums[i] <= 105
     * 1 <= k <= 109©leetcode
     */

    static void main() {
        int[] nums = {2, 2, 3, 1};
        int k = 4;
        System.out.println(minLength(nums, k));
    }

    static int minLength(int[] nums, int k) {
        int n = nums.length;
        Map<Integer, Integer> freq = new HashMap<>();

        long distinctSum = 0;
        int left = 0;
        int ans = Integer.MAX_VALUE;

        // required by problem statement
        int x = k;

        for (int right = 0; right < n; right++) {
            int val = nums[right];
            freq.put(val, freq.getOrDefault(val, 0) + 1);

            if (freq.get(val) == 1) {
                distinctSum += val;
            }

            while (distinctSum >= x) {
                ans = Math.min(ans, right - left + 1);

                int remove = nums[left];
                freq.put(remove, freq.get(remove) - 1);

                if (freq.get(remove) == 0) {
                    distinctSum -= remove;
                }
                left++;
            }
        }

        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

