package PrefixSum;

public class FindPivotIndex {
    //Leetcode - 724
    /**
     * Given an array of integers nums, calculate the pivot index of this array.
     *
     * The pivot index is the index where the sum of all the numbers strictly to the left of the index is equal to the sum of all the numbers strictly to the index's right.
     *
     * If the index is on the left edge of the array, then the left sum is 0 because there are no elements to the left. This also applies to the right edge of the array.
     *
     * Return the leftmost pivot index. If no such index exists, return -1.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [1,7,3,6,5,6]
     * Output: 3
     * Explanation:
     * The pivot index is 3.
     * Left sum = nums[0] + nums[1] + nums[2] = 1 + 7 + 3 = 11
     * Right sum = nums[4] + nums[5] = 5 + 6 = 11
     * Example 2:
     *
     * Input: nums = [1,2,3]
     * Output: -1
     * Explanation:
     * There is no index that satisfies the conditions in the problem statement.
     * Example 3:
     *
     * Input: nums = [2,1,-1]
     * Output: 0
     * Explanation:
     * The pivot index is 0.
     * Left sum = 0 (no elements to the left of index 0)
     * Right sum = nums[1] + nums[2] = 1 + -1 = 0
     *
     *
     * Constraints:
     *
     * 1 <= nums.length <= 104
     * -1000 <= nums[i] <= 1000
     */

    static void main() {
        int[] nums = {-1,-1,-1,1,1,1};
        System.out.println(pivotIndex(nums));
    }

    static int pivotIndex(int[] nums) {
        int[] arr = new int[nums.length];
        arr[0] = nums[0];
        for(int i = 1 ; i < nums.length ; i ++){
            arr[i] = arr[i - 1] + nums[i];
        }
        for(int i = 0 ; i < nums.length ; i ++){
            if(i == 0){
                if(arr[nums.length - 1] - arr[i] == 0){
                    return i;
                }
            } else if(i == nums.length - 1){
                if(arr[nums.length - 2] == 0){
                    return nums.length - 1;
                }
            } else{
                if(arr[i - 1] == arr[nums.length - 1] - arr[i]){
                    return i;
                }
            }
        }
        return -1;
    }
}

package PrefixSum;

public class MaxscoreAfterSplittingString {
    //Leetcode - 1422
    //https://leetcode.com/problems/maximum-score-after-splitting-a-string/?envType=problem-list-v2&envId=prefix-sum
    /**
     * Given a string s of zeros and ones, return the maximum score after splitting the string into two non-empty substrings (i.e. left substring and right substring).
     *
     * The score after splitting a string is the number of zeros in the left substring plus the number of ones in the right substring.
     *
     *
     *
     * Example 1:
     *
     * Input: s = "011101"
     * Output: 5
     * Explanation:
     * All possible ways of splitting s into two non-empty substrings are:
     * left = "0" and right = "11101", score = 1 + 4 = 5
     * left = "01" and right = "1101", score = 1 + 3 = 4
     * left = "011" and right = "101", score = 1 + 2 = 3
     * left = "0111" and right = "01", score = 1 + 1 = 2
     * left = "01110" and right = "1", score = 2 + 1 = 3
     * Example 2:
     *
     * Input: s = "00111"
     * Output: 5
     * Explanation: When left = "00" and right = "111", we get the maximum score = 2 + 3 = 5
     * Example 3:
     *
     * Input: s = "1111"
     * Output: 3
     *
     *
     * Constraints:
     *
     * 2 <= s.length <= 500
     * The string s consists of characters '0' and '1' only.
     */

    static void main() {
        String s = "011101";
        System.out.println(maxScore(s));
    }

    static int maxScore(String s) {
        int[] left = new int[s.length()];
        int[] right = new int[s.length()];
        if(s.charAt(0) == '0'){
            left[0] = 1;
            right[0] = 0;
        } else{
            left[0] = 0;
            right[0] = 1;
        }
        for(int i = 1 ; i < s.length() ; i ++){
            if(s.charAt(i) == '0'){
                left[i] = left[i - 1] + 1;
            } else{
                left[i] = left[i - 1];
            }
            if(s.charAt(i) == '1'){
                right[i] = right[i - 1] + 1;
            } else{
                right[i] = right[i -1];
            }
        }
        int max = 0;
        for(int i = 0 ; i < s.length() ; i ++){
            int x = left[i] + (right[s.length() - 1] - right[i]);
            if(x > max){
                max = x;
            }
        }
        return max;
    }
}

