public class MinValueToPositiveStepby {
    //Leetcode - 1413
    //https://leetcode.com/problems/minimum-value-to-get-positive-step-by-step-sum/description/?envType=problem-list-v2&envId=prefix-sum
    /**
     * Given an array of integers nums, you start with an initial positive value startValue.
     *
     * In each iteration, you calculate the step by step sum of startValue plus elements in nums (from left to right).
     *
     * Return the minimum positive value of startValue such that the step by step sum is never less than 1.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [-3,2,-3,4,2]
     * Output: 5
     * Explanation: If you choose startValue = 4, in the third iteration your step by step sum is less than 1.
     * step by step sum
     * startValue = 4 | startValue = 5 | nums
     *   (4 -3 ) = 1  | (5 -3 ) = 2    |  -3
     *   (1 +2 ) = 3  | (2 +2 ) = 4    |   2
     *   (3 -3 ) = 0  | (4 -3 ) = 1    |  -3
     *   (0 +4 ) = 4  | (1 +4 ) = 5    |   4
     *   (4 +2 ) = 6  | (5 +2 ) = 7    |   2
     * Example 2:
     *
     * Input: nums = [1,2]
     * Output: 1
     * Explanation: Minimum start value should be positive.
     * Example 3:
     *
     * Input: nums = [1,-2,-3]
     * Output: 5
     *
     *
     * Constraints:
     *
     * 1 <= nums.length <= 100
     * -100 <= nums[i] <= 100
     */

    static void main() {
        int[] nums = {-3,2,-3,4,2};
        System.out.println(minStartValue(nums));
    }

    static int minStartValue(int[] nums) {
        int sum = 0 ;
        int min = 0;
        for(int i = 0 ; i < nums.length ; i ++){
            sum += nums[i];
            min = Math.min(sum, min);
        }
        return 1 - min;
    }
}

package PrefixSum;

public class RangeSumQuery {
    //Leetcode - 303
    /**
     * Given an integer array nums, handle multiple queries of the following type:
     *
     * Calculate the sum of the elements of nums between indices left and right inclusive where left <= right.
     * Implement the NumArray class:
     *
     * NumArray(int[] nums) Initializes the object with the integer array nums.
     * int sumRange(int left, int right) Returns the sum of the elements of nums between indices left and right inclusive (i.e. nums[left] + nums[left + 1] + ... + nums[right]).
     *
     *
     * Example 1:
     *
     * Input
     * ["NumArray", "sumRange", "sumRange", "sumRange"]
     * [[[-2, 0, 3, -5, 2, -1]], [0, 2], [2, 5], [0, 5]]
     * Output
     * [null, 1, -1, -3]
     *
     * Explanation
     * NumArray numArray = new NumArray([-2, 0, 3, -5, 2, -1]);
     * numArray.sumRange(0, 2); // return (-2) + 0 + 3 = 1
     * numArray.sumRange(2, 5); // return 3 + (-5) + 2 + (-1) = -1
     * numArray.sumRange(0, 5); // return (-2) + 0 + 3 + (-5) + 2 + (-1) = -3
     *
     *
     * Constraints:
     *
     * 1 <= nums.length <= 104
     * -105 <= nums[i] <= 105
     * 0 <= left <= right < nums.length
     * At most 104 calls will be made to sumRange.
     */

    private static int[] arr;
    static void main() {
        int[] nums = {-2, 0, 3, -5, 2, -1};
        int[][] sum = {{0,2},{2,5},{0,5}};
        arr = new int[nums.length];
        arr[0] = nums[0];
        for(int i = 1; i < nums.length ; i ++){
            arr[i] = arr[i - 1] + nums[i];
        }
        for(int i = 0 ; i < sum.length ; i ++){
            int left = sum[i][0];
            int right = sum[i][1];
            System.out.println(sumRange(left, right));
        }
    }

    static int sumRange(int left, int right) {
        if(left == 0){
            return arr[right];
        }
        return  arr[right] - arr[left - 1] ;
    }
}

