            return  - 1;
        }
        int mid = start + (end - start) / 2;
        if(arr[mid] == target){
            return mid;
        } else if (arr[mid] > target) {
            return search(arr, target, start, mid - 1);
        } else{
            return search(arr, target, mid + 1, end);
        }
    }
}

