public class SearchInRotatedArray {
    static void main() {
        int[] arr = {5,6,7,8,9,1,2,3};
        int target = 50;
        System.out.println(searchInRotatedArray(arr, target, 0 , arr.length - 1));
    }

    static int searchInRotatedArray(int[] arr, int target, int start, int end){
        if(start > end){
            return -1;
        }
        int mid = start + (end - start) / 2;
        if(arr[mid] == target){
            return mid;
        }
        if(arr[start] <= arr[mid] && (arr[start] <= target && arr[mid] > target)){
            return searchInRotatedArray(arr, target, start, mid - 1);
        }
        return searchInRotatedArray(arr, target, mid + 1 , end);
    }
}

package Recursion;

import java.util.Arrays;

public class SelectionSort {
    static void main() {
        int[] arr = {32,42,1,5,6,245,6,3};
        selectionSort(arr, arr.length - 1,0, 0);
        System.out.println(Arrays.toString(arr));
    }

    static void selectionSort(int[] arr, int i, int j, int max){
        if(i == 0){
            return;
        }
        if(j < i){
            if(arr[j] > arr[max]){
                selectionSort(arr, i, j + 1, j); //arr[j] will be the new max
            } else{
                selectionSort(arr, i , j + 1, max);
            }
        } else {
            int temp = arr[max];
            arr[max] = arr[i];
            arr[i] = temp;
            selectionSort(arr, i - 1, 0 , 0);
        }
    }
}

package Recursion;

public class StepsToReduceToZero {
    //Leetcode - 1342
    //https://leetcode.com/problems/number-of-steps-to-reduce-a-number-to-zero/description/
    /**
     * Given an integer num, return the number of steps to reduce it to zero.
     *
     * In one step, if the current number is even, you have to divide it by 2, otherwise, you have to subtract 1 from it.
     *
     *
     *
     * Example 1:
     *
     * Input: num = 14
     * Output: 6
     * Explanation:
     * Step 1) 14 is even; divide by 2 and obtain 7.
     * Step 2) 7 is odd; subtract 1 and obtain 6.
     * Step 3) 6 is even; divide by 2 and obtain 3.
     * Step 4) 3 is odd; subtract 1 and obtain 2.
     * Step 5) 2 is even; divide by 2 and obtain 1.
     * Step 6) 1 is odd; subtract 1 and obtain 0.
     * Example 2:
     *
     * Input: num = 8
     * Output: 4
     * Explanation:
     * Step 1) 8 is even; divide by 2 and obtain 4.
     * Step 2) 4 is even; divide by 2 and obtain 2.
     * Step 3) 2 is even; divide by 2 and obtain 1.
     * Step 4) 1 is odd; subtract 1 and obtain 0.
     * Example 3:
     *
     * Input: num = 123
     * Output: 12
     */

    static void main() {
        int num = 14;
        System.out.println(recursiveCall(num, 0));
    }

    static int recursiveCall(int num, int count){
        if(num == 0){
            return count;
        }
        if(num % 2 == 0){
            return recursiveCall(num/2,count + 1);
        } else{
            return recursiveCall(num-1,count + 1);
        }
    }
}

package Recursion;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SubSequence {
    static void main() {
        String s = "abc";
        subSequence("", s); //proceesed will be empty initially
        System.out.println(subSequenceAsList("", s));
        subsequenceAscii("", s);
    }

    static void subSequence(String processed, String s){
        if(s.isEmpty()){
            System.out.println(processed);
            return;
        }
        subSequence(processed + s.charAt(0), s.substring(1)); //taking a character
        subSequence(processed, s.substring(1)); //rejecting a character
    }

    static ArrayList<String> subSequenceAsList(String processed, String s){
        if(s.isEmpty()){
            ArrayList<String> res = new ArrayList<>();
            res.add(processed);
            return res;
        }

        ArrayList<String> left = subSequenceAsList(processed + s.charAt(0), s.substring(1));
        ArrayList<String> right = subSequenceAsList(processed, s.substring(1));
        left.addAll(right);
        return left;
    }

    static void subsequenceAscii(String p, String up){
        if(up.isEmpty()){
            System.out.println(p);
            return;
        }

        subsequenceAscii(p + up.charAt(0), up.substring(1));
        subsequenceAscii(p, up.substring(1));
        subsequenceAscii(p + (up.charAt(0) + 0), up.substring(1));
    }
}

