        }
        else {
            printTriangleStaight(row - 1, 0);
            System.out.println();
        }
    }
}

package Recursion.BackTracking;

public class AllPathsWithObstacles {
    //We can move in all 4 directions
    static void main() {
        boolean[][] maze = {{true, true, true},{true, true, true}, {true, true, true}};
        printPathWithObstacles("", maze, 0, 0);
    }

    static void printPathWithObstacles(String path, boolean[][] maze, int row, int col){
        if(row == maze.length - 1 && col == maze[0].length - 1){
            System.out.println(path);
            return;
        }
        if(!maze[row][col]){
            return;
        }
        maze[row][col] = false; //already visited path so its false
        if(row > 0){
            printPathWithObstacles(path + 'U', maze, row - 1, col); //going up
        }
        if(col > 0){
            printPathWithObstacles(path + 'L', maze, row, col - 1); //going left
        }
        if(row < maze.length - 1){
            printPathWithObstacles(path + 'D', maze, row + 1, col); //going down
        }
        if (col < maze[0].length - 1){
            printPathWithObstacles(path + 'R', maze, row, col + 1); //going right
        }
        //here is where a fn gets over
        //before fn getting removed from stack we are backtracking the  changed values to original value.
        maze[row][col] = true;
    }
}

package Recursion.BackTracking;

import java.util.ArrayList;
import java.util.List;

public class CombinationSum {
    //39
    //https://leetcode.com/problems/combination-sum/description/?envType=problem-list-v2&envId=backtracking
    /**
     * Given an array of distinct integers candidates and a target integer target, return a list of all unique combinations of candidates where the chosen numbers sum to target. You may return the combinations in any order.
     *
     * The same number may be chosen from candidates an unlimited number of times. Two combinations are unique if the frequency of at least one of the chosen numbers is different.
     *
     * The test cases are generated such that the number of unique combinations that sum up to target is less than 150 combinations for the given input.
     *
     *
     *
     * Example 1:
     *
     * Input: candidates = [2,3,6,7], target = 7
     * Output: [[2,2,3],[7]]
     * Explanation:
     * 2 and 3 are candidates, and 2 + 2 + 3 = 7. Note that 2 can be used multiple times.
     * 7 is a candidate, and 7 = 7.
     * These are the only two combinations.
     * Example 2:
     *
     * Input: candidates = [2,3,5], target = 8
     * Output: [[2,2,2,2],[2,3,3],[3,5]]
     * Example 3:
     *
     * Input: candidates = [2], target = 1
     * Output: []
     *
     *
     * Constraints:
     *
     * 1 <= candidates.length <= 30
     * 2 <= candidates[i] <= 40
     * All elements of candidates are distinct.
     * 1 <= target <= 40
     */

    static void main() {
        int[] candidates = {2,3,6,7};
        int target = 7;
        List<List<Integer>> ans = new ArrayList<>();
        backTrack(ans, new ArrayList<>(), candidates, target, 0);
        System.out.println(ans);
    }

    static void backTrack(List<List<Integer>> list, List<Integer> temp, int[] nums, int target, int start){
        if(target < 0){
            return;
        }
        if(target == 0){ //if target is 0 we found the exact combination sum
            list.add(new ArrayList<>(temp));
        }
        for(int i = start ; i < nums.length ; i ++){
            temp.add(nums[i]);
            backTrack(list, temp, nums, target - nums[i], i); //we want to subtract current value from target and send to next recursion to find balance sum
            temp.remove(temp.size() - 1); //back track remove last element;
        }
    }
}

package Recursion.BackTracking;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class LeetCodeNQueens {
    //51
    //https://leetcode.com/problems/n-queens/description/
    /**
     * The n-queens puzzle is the problem of placing n queens on an n x n chessboard such that no two queens attack each other.
     *
     * Given an integer n, return all distinct solutions to the n-queens puzzle. You may return the answer in any order.
     *
     * Each solution contains a distinct board configuration of the n-queens' placement, where 'Q' and '.' both indicate a queen and an empty space, respectively.
     *
     *
     *
     * Example 1:
     *
     *
     * Input: n = 4
     * Output: [[".Q..","...Q","Q...","..Q."],["..Q.","Q...","...Q",".Q.."]]
     * Explanation: There exist two distinct solutions to the 4-queens puzzle as shown above
     * Example 2:
     *
     * Input: n = 1
     * Output: [["Q"]]
     *
     *
     * Constraints:
     *
     * 1 <= n <= 9
     */
    //Time complexity - O(N!)

    static void main() {
        int n = 4;
        System.out.println(solveNQueens(n));
    }

    static List<List<String>> solveNQueens(int n) {
        String[][] board = new String[n][n];
        for(String[] row: board){
            Arrays.fill(row,"."); //Filling intital board with all '.'
        }
        List<List<String>> ans = new ArrayList<>();
        return queenBackTrack(board, 0, ans);
    }

    static List<List<String>> queenBackTrack(String[][] board, int row, List<List<String>> ans){
        if(row == board.length){ //base condition that it we passed over all rows
            List<String> temp = new ArrayList<>();
            for(String[] boardRow : board){
                temp.add(String.join("",boardRow));
            }
            ans.add(temp); //if we passed over all rows we found a way where we can place N queens in board
        }
        for(int col = 0 ; col < board.length ; col ++){
            if(isSafe(board, row, col)){ //check if safe to place queen in current row for current col.
                board[row][col] = "Q"; //if safe mark as Q
                queenBackTrack(board, row + 1, ans);
                board[row][col] = "."; //backtrack make the path to '.' if this recursive call is not the answer
            }
        }
        return ans; //code will come here once all recursive calls are over
    }
    static boolean isSafe(String[][] board, int row, int col){
        //check vertical from 0 to row
        for(int i = 0 ; i < row ; i ++){
            if(board[i][col] == "Q"){
                return false;
            }
        }
        //check diagonal left from current row-1,col-1 to row - (min(row,col)), col - min(row,col)
        int maxLeft = Math.min(row, col);
        for(int i = 1; i <= maxLeft ; i ++){
            if(board[row - i][col - i] == "Q"){
                return false;
            }
        }
        //checking diagonal right from current row-1,col+1 to row - min(row, total-col-1), col - min(row, total-col-1)
        int maxRight = Math.min(row, board.length - col - 1);
        for(int i = 1 ; i <= maxRight ; i ++){
            if(board[row - i][col + i] == "Q"){
                return false;
            }
        }
        return true;
    }
}

package Recursion.BackTracking;

public class LeetcodeSudokuSolver {
    //37
    //https://leetcode.com/problems/sudoku-solver/description/
    /**
     * Write a program to solve a Sudoku puzzle by filling the empty cells.
     *
     * A sudoku solution must satisfy all of the following rules:
     *
     * Each of the digits 1-9 must occur exactly once in each row.
     * Each of the digits 1-9 must occur exactly once in each column.
     * Each of the digits 1-9 must occur exactly once in each of the 9 3x3 sub-boxes of the grid.
     * The '.' character indicates empty cells.
     *
     *
     *
     * Example 1:
     *
     *
     * Input: board = [{'5','3','.','.','7','.','.','.','.'},{'6','.','.','1','9','5','.','.','.'},{'.','9','8','.','.','.','.','6','.'},{'8','.','.','.','6','.','.','.','3'},{'4','.','.','8','.','3','.','.','1'},{'7','.','.','.','2','.','.','.','6'},{'.','6','.','.','.','.','2','8','.'},{'.','.','.','4','1','9','.','.','5'},{'.','.','.','.','8','.','.','7','9'}]
     * Output: [{'5','3','4','6','7','8','9','1','2'},{'6','7','2','1','9','5','3','4','8'},{'1','9','8','3','4','2','5','6','7'},{'8','5','9','7','6','1','4','2','3'},{'4','2','6','8','5','3','7','9','1'},{'7','1','3','9','2','4','8','5','6'},{'9','6','1','5','3','7','2','8','4'},{'2','8','7','4','1','9','6','3','5'},{'3','4','5','2','8','6','1','7','9'}]
     * Explanation: The input board is shown above and the only valid solution is shown below:
     *
     *
     *
     *
     * Constraints:
     *
     * board.length == 9
     * board[i].length == 9
     * board[i][j] is a digit or '.'.
     * It is guaranteed that the input board has only one solution.
     */

    static void main() {
        char[][] board = {
                {'5','3','.','.','7','.','.','.','.'},
                {'6','.','.','1','9','5','.','.','.'},
                {'.','9','8','.','.','.','.','6','.'},
                {'8','.','.','.','6','.','.','.','3'},
                {'4','.','.','8','.','3','.','.','1'},
                {'7','.','.','.','2','.','.','.','6'},
                {'.','6','.','.','.','.','2','8','.'},
                {'.','.','.','4','1','9','.','.','5'},
                {'.','.','.','.','8','.','.','7','9'}
        };
        int[][] ans = new int[9][9];
        for(int i = 0 ; i < 9 ; i ++){
            for(int j = 0 ; j < 9 ; j ++){
                if(board[i][j] == '.'){
                    ans[i][j] = 0;
                } else{
                    ans[i][j] = board[i][j] - '0';
                }
            }
        }
        solve(ans);
        for(int i = 0 ; i < 9 ; i ++){
            for(int j = 0 ; j < 9 ; j ++){
                board[i][j] = (char)(ans[i][j] + '0');
            }
        }
        for (int i = 0 ;i < 9 ; i ++){
            for(int j = 0 ; j < 9 ; j ++){
                System.out.print(board[i][j]  + " ");
            }
            System.out.println();
        }
    }

    static boolean solve(int[][] board){
        int n = board.length;
        int row = -1;
        int col = -1;
        boolean emptyLeft = true; //check for any empty spot available to fill the sudoku
        for (int i = 0 ; i < n ; i ++){
            for(int j = 0 ; j < n ; j ++){
                if (board[i][j] == 0){ //0 is the empty places in the board
                    row = i;
                    col = j;
                    emptyLeft = false; //empty found
                    break;
                }
            }
            if(!emptyLeft){// if we found the empty in this row then break the loop
                break;
            }
        }
        if(emptyLeft){
            return true; // if no empty left in sudoku then it is solved so return true
        }
        //backtrack
        for(int number = 1 ; number <= 9 ; number ++){ //numbers inside suduko is from 1 to 9
            if (isSafe(board, row, col, number)){
                board[row][col] = number;
                if(solve(board)){
                    //found the answer
                    return true;
                } else{
                    board[row][col] = 0;
                }
            }
        }
        return false;
    }

    static boolean isSafe(int[][] board, int row, int col, int num){
        //check the entire row and col
        for(int i = 0 ; i < board.length ; i ++){
            //check the number is already in that row in board
            if(board[row][i] == num){
                return false;
            }
            //check the number is already in that col in board
            if(board[i][col] == num){
                return false;
            }
        }
        //check inner squares
        int sqrt = (int) Math.sqrt(board.length); //for variable inputs like n = 5,...
        int rowStart = row - row % sqrt;
        int colStart = col - col % sqrt;
        for(int i = rowStart ; i < rowStart + sqrt ; i ++){
            for(int j = colStart ; j < colStart + sqrt ; j ++){
                if(board[i][j] == num){
                    return false;
                }
            }
        }
        return true;
    }
}

package Recursion.BackTracking;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class MaxLengthOfConcatString {
    //1239
    //https://leetcode.com/problems/maximum-length-of-a-concatenated-string-with-unique-characters/?envType=problem-list-v2&envId=backtracking
    /**
     * You are given an array of strings arr. A string s is formed by the concatenation of a subsequence of arr that has unique characters.
     *
     * Return the maximum possible length of s.
     *
     * A subsequence is an array that can be derived from another array by deleting some or no elements without changing the order of the remaining elements.
     *
     *
     *
     * Example 1:
     *
     * Input: arr = ["un","iq","ue"]
     * Output: 4
     * Explanation: All the valid concatenations are:
     * - ""
     * - "un"
     * - "iq"
     * - "ue"
     * - "uniq" ("un" + "iq")
     * - "ique" ("iq" + "ue")
     * Maximum length is 4.
     * Example 2:
     *
     * Input: arr = ["cha","r","act","ers"]
     * Output: 6
     * Explanation: Possible longest valid concatenations are "chaers" ("cha" + "ers") and "acters" ("act" + "ers").
     * Example 3:
     *
     * Input: arr = ["abcdefghijklmnopqrstuvwxyz"]
     * Output: 26
     * Explanation: The only string in arr has all 26 characters.
     *
     *
     * Constraints:
     *
     * 1 <= arr.length <= 16
     * 1 <= arr[i].length <= 26
     * arr[i] contains only lowercase English letters.
     */

    static void main(String[] args) {
        List<String> inp = new ArrayList<>();
        inp.add("cha");
        inp.add("r");
        inp.add("act");
        inp.add("ers");
        List<List<String>> res = new ArrayList<>();
        int maxLength = 0;
        backTrack(res, new ArrayList<>(), inp, 0);
        for (List<String> list : res){
            String s = String.join("", list);
            if(isUnique(s)){
                maxLength = Math.max(maxLength, s.length());
            }
        }
        System.out.println(maxLength); //800ms
        //method 2
        System.out.println(maxLengthFn(inp)); //24ms
    }

    static void backTrack(List<List<String>> res, List<String> temp, List<String> inp, int start){
        res.add(new ArrayList<>(temp));
        for(int i = start ; i < inp.size() ; i ++){
            temp.add(inp.get(i));
            backTrack(res, temp, inp, i +1);
            temp.remove(temp.size() - 1);
        }
    }

    static boolean isUnique(String s){
        Set<Character> uniqueSet = new HashSet<>();
        for(char i : s.toCharArray()){
            if(uniqueSet.contains(i)){
                return false;
            }
            uniqueSet.add(i);
        }
        return true;
    }

    //method 2
    private static int result = 0;
    static int maxLengthFn(List<String> arr) {
        if (arr == null || arr.size() == 0)    return 0;

        dfs(arr, "", 0);
        return result;
    }

    static void dfs(List<String> arr, String path, int idx) {
        boolean isUniqueChar = isUniqueChars(path);

        if (isUniqueChar) {
            result = Math.max(path.length(), result);
        }

        if (idx == arr.size() || !isUniqueChar) {
            return;
        }

        for (int i = idx; i < arr.size(); i++) {
            dfs(arr, path + arr.get(i), i + 1);
        }

    }

    static boolean isUniqueChars(String s) {
        Set<Character> set = new HashSet<>();
        for (char c : s.toCharArray()) {
            if (set.contains(c)) {
                return false;
            }
            set.add(c);
        }
        return true;
    }
}

