import java.util.ArrayList;
import java.util.List;

public class SubsetXor {
    //1863
    //https://leetcode.com/problems/sum-of-all-subset-xor-totals/?envType=problem-list-v2&envId=backtracking
    /**
     * The XOR total of an array is defined as the bitwise XOR of all its elements, or 0 if the array is empty.
     *
     * For example, the XOR total of the array [2,5,6] is 2 XOR 5 XOR 6 = 1.
     * Given an array nums, return the sum of all XOR totals for every subset of nums.
     *
     * Note: Subsets with the same elements should be counted multiple times.
     *
     * An array a is a subset of an array b if a can be obtained from b by deleting some (possibly zero) elements of b.
     *
     *
     *
     * Example 1:
     *
     * Input: nums = [1,3]
     * Output: 6
     * Explanation: The 4 subsets of [1,3] are:
     * - The empty subset has an XOR total of 0.
     * - [1] has an XOR total of 1.
     * - [3] has an XOR total of 3.
     * - [1,3] has an XOR total of 1 XOR 3 = 2.
     * 0 + 1 + 3 + 2 = 6
     * Example 2:
     *
     * Input: nums = [5,1,6]
     * Output: 28
     * Explanation: The 8 subsets of [5,1,6] are:
     * - The empty subset has an XOR total of 0.
     * - [5] has an XOR total of 5.
     * - [1] has an XOR total of 1.
     * - [6] has an XOR total of 6.
     * - [5,1] has an XOR total of 5 XOR 1 = 4.
     * - [5,6] has an XOR total of 5 XOR 6 = 3.
     * - [1,6] has an XOR total of 1 XOR 6 = 7.
     * - [5,1,6] has an XOR total of 5 XOR 1 XOR 6 = 2.
     * 0 + 5 + 1 + 6 + 4 + 3 + 7 + 2 = 28
     * Example 3:
     *
     * Input: nums = [3,4,5,6,7,8]
     * Output: 480
     * Explanation: The sum of all XOR totals for every subset is 480.
     *
     *
     * Constraints:
     *
     * 1 <= nums.length <= 12
     * 1 <= nums[i] <= 20
     */
    static void main() {
        int[] nums = {5,1,6};
        System.out.println(subsetXORSum(nums));
    }

    static int subsetXORSum(int[] nums) {
        int total = 0;
        List<Integer> totalSum = new ArrayList<>();
        backTrackXor(nums, new ArrayList<Integer>(), totalSum, 0);
        for (int i : totalSum){
            total += i;
        }
        return total;
    }

    static void backTrackXor(int[] nums, List<Integer> temp, List<Integer> total, int start){
        if(temp.size() > 0)
            total.add(xorAction(new ArrayList<>(temp)));
        for(int i = start ; i < nums.length ; i ++){
            temp.add(nums[i]);
            backTrackXor(nums, temp, total, i + 1);
            temp.remove(temp.size() - 1);
        }
    }

    static int xorAction(List<Integer> temp){
        int x = temp.get(0);
        for(int i = 1 ; i < temp.size() ; i ++){
            x ^= temp.get(i);
        }
        return x;
    }
}

